CREATE TABLE IF NOT EXISTS gis_inec_content_validation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phase text NOT NULL, canonical_source_key text NOT NULL, artifact_scope text NOT NULL, candidate_count integer NOT NULL DEFAULT 0, validated_count integer NOT NULL DEFAULT 0, confirmed_count integer NOT NULL DEFAULT 0, insufficient_count integer NOT NULL DEFAULT 0, conflict_count integer NOT NULL DEFAULT 0, unverified_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'RUNNING', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS gis_inec_content_validation_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_inec_content_validation_runs(id), candidate_match_id uuid NOT NULL, lga_snapshot_id uuid, ward_snapshot_id uuid, state_id integer, lga_id integer, artifact_sha256 text, canonical_source_key text NOT NULL, evidence_decision text NOT NULL, content_validation jsonb NOT NULL DEFAULT '{}'::jsonb, errors jsonb NOT NULL DEFAULT '[]'::jsonb, decision_fingerprint text NOT NULL UNIQUE, candidate_status_before text NOT NULL, candidate_mutation boolean NOT NULL DEFAULT false, validated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,candidate_match_id));
CREATE INDEX IF NOT EXISTS gis_inec_content_validation_candidate_idx ON gis_inec_content_validation_decisions(candidate_match_id,validated_at DESC);
CREATE INDEX IF NOT EXISTS gis_inec_content_validation_snapshot_idx ON gis_inec_content_validation_decisions(ward_snapshot_id);